<script setup lang="ts">
import{ref,watch,inject}from'vue';import{useRoute}from'vue-router';import{ApiError}from'../api';import{useTicketWork}from'../ticket-work';import{ticketReadDenied,isObjectReadDenied}from'../ticket-access';import{reopenApi,validRound,type RoundSummary}from'../ticket-reopen-api';import type{TicketDetail}from'../ticket-api';import{statusLabel}from'../ticket-flow';
const props=defineProps<{ticket:TicketDetail}>(),route=useRoute(),work=useTicketWork(()=>route.fullPath),deny=inject(ticketReadDenied,undefined),items=ref<RoundSummary[]>([]),total=ref(0),page=ref(1);
const stamp=()=>JSON.stringify([props.ticket.id,props.ticket.roundId,props.ticket.rowVersion,props.ticket.currentRoundId]);
async function load(next=1){const expected=stamp(),scope=work.begin(()=>expected===stamp());items.value=[];total.value=0;try{const r=await reopenApi.rounds(props.ticket.id,next);if(!scope.current())return;if(!Array.isArray(r.items)||r.items.some(x=>!validRound(x,props.ticket.id))||new Set(r.items.map(r=>r.roundId)).size!==r.items.length)throw new ApiError(503,'ROUND_PROJECTION_INVALID','轮次目录无法确认，停止显示');items.value=r.items;total.value=r.total;page.value=r.page}catch(e){if(scope.current()&&isObjectReadDenied(e))deny?.();work.fail(e,scope)}finally{scope.finish()}}
watch(stamp,()=>void load(),{immediate:true});
</script>
<template><section class="panel ticket-rounds"><h2>处理轮次与历史</h2><p>当前展示第 {{ticket.roundNo||1}} 轮 · {{ticket.roundId}} · 起点 {{ticket.roundStartedAt||ticket.timing?.roundStartedAt}} · 生效规则 {{ticket.ruleVersion||ticket.sla?.policyVersion||'待核对'}}</p><p v-if="ticket.isHistorical||ticket.readOnly" class="notice">历史轮次只读；旧方案、决定、关闭事实及草稿不能驱动当前轮。<RouterLink :to="`/tickets/${ticket.id}`">重新查询当前轮</RouterLink></p><p v-else-if="!ticket.firstResponseAt" class="notice">本轮尚无首次人工响应事实。主管批准、分派和内部接单不算首响，待分派/待接单期间SLA继续。</p><p v-if="work.message.value" role="alert">{{work.message.value}}</p><article v-for="r in items" :key="r.roundId" class="record-entry round-entry"><RouterLink :to="r.current?`/tickets/${ticket.id}`:`/tickets/${ticket.id}/rounds/${r.roundId}`">第 {{r.roundNo}} 轮 · {{r.current?'当前':'历史只读'}} · {{statusLabel(r.status)}}</RouterLink><p>起点 {{r.startedAt}} · {{r.priority}} · 规则 {{r.ruleVersion}} · 首次人工响应 {{r.firstResponseAt||'尚无'}} · 终结 {{r.endedAt||'尚未终结'}}</p></article><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev, pager, next, total" @current-change="load"/><el-button :disabled="work.busy.value" @click="load(page)">重新查询轮次目录</el-button></section></template>
